WITH order_payment AS ( SELECT o.order_id, o.member_id, o.total_amount,
/* 주문별 완료 입금액 */ COALESCE( SUM(p.payment_amount) FILTER ( WHERE p.payment_status = 'COMPLETED' ), 0 ) AS paid_amount
FROM shop_order o
LEFT JOIN shop_payment p ON o.order_id = p.order_id
WHERE o.payment_type = 'CREDIT' AND o.order_status != 'CANCELLED'
GROUP BY o.order_id, o.member_id, o.total_amount ), member_receivable AS ( SELECT member_id,
/* 외상 주문 총금액 */ SUM(total_amount) AS total_credit_amount,
/* 완료된 누적 입금액 */ SUM(paid_amount) AS total_paid_amount,
/* 현재 미수금 */ SUM( GREATEST(total_amount - paid_amount, 0) ) AS receivable_amount
FROM order_payment
GROUP BY member_id )
SELECT m.member_id, m.member_name,
COALESCE(r.total_credit_amount, 0) AS total_credit_amount,
COALESCE(r.total_paid_amount, 0) AS total_paid_amount,
COALESCE(r.receivable_amount, 0) AS receivable_amount,
/* 외상 주문 가능 잔여 한도 */ GREATEST( 2000000 - COALESCE(r.receivable_amount, 0), 0 ) AS available_credit_amount
FROM member m
LEFT JOIN member_receivable r ON m.member_id = r.member_id
WHERE m.member_id = #{memberId}

SELECT o.order_id, o.order_no, o.member_id, o.address_id, o.address_name, o.order_status, COALESCE(oc.code_name, o.order_status) AS order_status_name, o.payment_type, o.payment_status, COALESCE(pc.code_name, o.payment_status) AS payment_status_name, o.total_amount, o.created_at FROM shop_order o LEFT JOIN common_code oc ON oc.group_code = 'ORDER_STATUS' AND oc.code = o.order_status AND oc.use_yn = 'Y' LEFT JOIN common_code pc ON pc.group_code = 'PAYMENT_STATUS' AND pc.code = o.payment_status AND pc.use_yn = 'Y' WHERE o.member_id = #{memberId}
AND o.address_id = #{addressId}
ORDER BY o.created_at DESC, o.order_id DESC

